/**
 * @brief Console output hook for the menu engine.
 * @param s Text.
 * @param n Number of characters.
 * @return None.
 */
static void cli_io_write(const char *s, size_t n)
{
    plat_console_write(s, n);
}

/**
 * @brief Parse an unsigned 32-bit number, "0x" hexadecimal or decimal.
 * @param s   Text (whole string must be a number).
 * @param out Parsed value.
 * @return 0 on success, -1 on an empty string, a bad digit or overflow.
 */
static int cli_parse_u32(const char *s, uint32_t *out)
{
    uint32_t v = 0;
    unsigned base = 10u;
    int digits = 0;
    if (s == NULL) {
        return -1;
    }
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
        base = 16u;
        s += 2;
    }
    for (; *s != '\0'; s++) {
        unsigned d;
        char c = *s;
        if (c >= '0' && c <= '9') {
            d = (unsigned)(c - '0');
        } else if (base == 16u && c >= 'a' && c <= 'f') {
            d = (unsigned)(c - 'a' + 10);
        } else if (base == 16u && c >= 'A' && c <= 'F') {
            d = (unsigned)(c - 'A' + 10);
        } else if (c == '_' && base == 16u) {
            continue;
        } else {
            return -1;
        }
        if (v > (0xFFFFFFFFu - d) / base) {
            return -1;
        }
        v = v * base + d;
        digits++;
    }
    if (digits == 0) {
        return -1;
    }
    *out = v;
    return 0;
}

/**
 * @brief Parse a dotted-quad IPv4 address.
 * @param s   Text "a.b.c.d", each part 0..255.
 * @param out Address, first octet in bits [31:24].
 * @return 0 on success, -1 on a malformed address.
 */
static int cli_parse_ipv4(const char *s, uint32_t *out)
{
    uint32_t addr = 0;
    for (int part = 0; part < 4; part++) {
        uint32_t v = 0;
        int digits = 0;
        while (*s >= '0' && *s <= '9') {
            v = v * 10u + (uint32_t)(*s - '0');
            if (v > 255u) {
                return -1;
            }
            s++;
            digits++;
        }
        if (digits == 0 || digits > 3) {
            return -1;
        }
        addr = (addr << 8) | v;
        if (part < 3) {
            if (*s != '.') {
                return -1;
            }
            s++;
        }
    }
    if (*s != '\0') {
        return -1;
    }
    *out = addr;
    return 0;
}

/**
 * @brief Format an IPv4 address as dotted quad.
 * @param a   Address, first octet in bits [31:24].
 * @param buf Output buffer of at least 16 characters.
 * @return buf.
 */
static const char *cli_ipv4_text(uint32_t a, char buf[16])
{
    (void)fmt_snprintf(buf, 16u, "%u.%u.%u.%u", (unsigned)(a >> 24), (unsigned)((a >> 16) & 0xFFu),
                       (unsigned)((a >> 8) & 0xFFu), (unsigned)(a & 0xFFu));
    return buf;
}

/**
 * @brief Print a 0xMMDDYYYY date code as MM-DD-YYYY.
 * @param v Date code.
 * @return None.
 */
static void cli_print_datecode(uint32_t v)
{
    fmt_printf("%02x-%02x-%04x", (unsigned)(v >> 24), (unsigned)((v >> 16) & 0xFFu), (unsigned)(v & 0xFFFFu));
}

/**
 * @brief Print a frequency given in kHz as MHz with three decimals.
 * @param khz Frequency in kHz.
 * @return None.
 */
static void cli_print_mhz(uint32_t khz)
{
    fmt_printf("%u.%03u MHz", (unsigned)(khz / 1000u), (unsigned)(khz % 1000u));
}

/**
 * @brief Probe a core and report when it is absent from the build.
 * @param core Core descriptor (name, window base, expected ID).
 * @return 1 when present (prints its header and the driver note), 0 when
 *         absent (prints "<core> not present in this build").
 */
static int cli_core_check(const cli_core_t *core)
{
    board_probe_t p;
    char want[5];
    char got[5];
    board_id_text(core->id, want);
    if (!board_probe(core->base, core->id, &p)) {
        fmt_printf("%% %s not present in this build (ID 0x%08X at 0x%08X, expected 0x%08X \"%s\")\n",
                   core->name, (unsigned)p.id, (unsigned)core->base, (unsigned)core->id, want);
        return 0;
    }
    board_id_text(p.id, got);
    fmt_printf("%s core present at 0x%08X: ID \"%s\", register map ", core->name, (unsigned)core->base, got);
    cli_print_datecode(p.version);
    fmt_printf(", CAPS 0x%08X\n", (unsigned)p.caps);
    fmt_printf("  (detailed status needs the %s driver, not integrated in this firmware)\n", core->name);
    return 1;
}

/**
 * @brief Note for a configuration change: stored, and whether it reached hardware.
 * @param core Core the setting belongs to.
 * @return None.
 */
static void cli_config_note(const cli_core_t *core)
{
    board_probe_t p;
    if (!board_probe(core->base, core->id, &p)) {
        fmt_printf("%% %s not present in this build; setting kept in the running configuration\n", core->name);
    } else {
        fmt_printf("%% %s driver not integrated; setting kept in the running configuration\n", core->name);
    }
}

/**
 * @brief Report a bad parameter value.
 * @param what Parameter name.
 * @param val  Value as typed.
 * @return -1 (for the caller to return).
 */
static int cli_bad_value(const char *what, const char *val)
{
    fmt_printf("%% Invalid %s \"%s\"\n", what, (val != NULL) ? val : "");
    return -1;
}

