/**
 * @brief SHOW VERSION: board ID, register map, build ID and tree state,
 *        network capability, firmware name and build date.
 * @param ctx Unused.
 * @return 0, or -1 when the board system registers do not answer.
 */
int cli_show_version(const MenuCommandContext *ctx)
{
    uint32_t id  = board_sys_read(NXV_SYS_ID);
    uint32_t ver = board_sys_read(NXV_SYS_VERSION);
    uint32_t bid = board_sys_read(NXV_SYS_BUILD_ID);
    uint32_t dty = board_sys_read(NXV_SYS_BUILD_DIRTY) & 1u;
    uint32_t cap = board_sys_read(NXV_SYS_CAPS);
    char idt[5];
    (void)ctx;
    board_id_text(id, idt);
    fmt_printf("RTLNet Nexys Video\n");
    fmt_printf("  Board ID        : %s (0x%08X)%s\n", idt, (unsigned)id,
               (id == NXV_SYS_ID_VALUE) ? "" : "  % unexpected, system registers not found");
    fmt_printf("  Register map    : ");
    cli_print_datecode(ver);
    fmt_printf(" (0x%08X)\n", (unsigned)ver);
    fmt_printf("  Build ID        : 0x%08x (git %08x), tree %s\n", (unsigned)bid, (unsigned)bid, dty ? "dirty" : "clean");
    fmt_printf("  Network cores   : %s\n", (cap & NXV_CAPS_NETWORK) ? "in this build" : "not in this build (CPU-only)");
    fmt_printf("  Firmware        : %s %s, built %s %s\n", RTLNET_FW_NAME, RTLNET_FW_VERSION, __DATE__, __TIME__);
    return (id == NXV_SYS_ID_VALUE) ? 0 : -1;
}

/**
 * @brief SHOW SYSTEM: MMCM lock, uptime, CPU clock, measured clocks,
 *        switches, buttons, LEDs and PHY pin levels.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_system(const MenuCommandContext *ctx)
{
    static const char *const clk_names[NXV_CLK_MEAS_COUNT] = {
        "clk125", "clk125_90", "clk200", "axis_clk", "proto_clk"
    };
    static const unsigned clk_nominal_khz[NXV_CLK_MEAS_COUNT] = { 125000u, 125000u, 200000u, 62500u, 50000u };
    static const char btn_names[5] = { 'C', 'D', 'L', 'R', 'U' };
    uint32_t cs   = board_sys_read(NXV_SYS_CLK_STATUS);
    uint32_t up   = board_sys_read(NXV_SYS_UPTIME_MS);
    uint32_t hz   = board_sys_read(NXV_SYS_CPU_CLK_HZ);
    uint32_t sw   = board_sys_read(NXV_SYS_SWITCHES) & 0xFFu;
    uint32_t btn  = board_sys_read(NXV_SYS_BUTTONS) & 0x1Fu;
    uint32_t leds = board_sys_read(NXV_SYS_LEDS) & 0xFFu;
    uint32_t phy  = board_sys_read(NXV_SYS_PHY_STATUS);
    uint32_t s    = up / 1000u;
    (void)ctx;

    fmt_printf("System\n");
    fmt_printf("  MMCM            : %s\n", (cs & NXV_CLK_MMCM_LOCKED) ? "locked" : "NOT locked");
    fmt_printf("  Uptime          : %ud %02u:%02u:%02u.%03u (%u ms since reset release; firmware %u ms)\n",
               (unsigned)(s / 86400u), (unsigned)((s / 3600u) % 24u), (unsigned)((s / 60u) % 60u),
               (unsigned)(s % 60u), (unsigned)(up % 1000u), (unsigned)up, (unsigned)plat_uptime_ms());
    fmt_printf("  CPU clock       : %u Hz\n", (unsigned)hz);
    for (unsigned i = 0; i < NXV_CLK_MEAS_COUNT; i++) {
        uint32_t khz = board_clk_khz(i);
        fmt_printf("  Clock %-10s: ", clk_names[i]);
        cli_print_mhz(khz);
        fmt_printf("  (nominal ");
        cli_print_mhz(clk_nominal_khz[i]);
        fmt_printf(")%s\n", (cs & (1u << (NXV_CLK_ALIVE_SHIFT + i))) ? "" : "  STOPPED");
    }
    fmt_printf("  Switches        : 0x%02X  (sw7..sw0 =", (unsigned)sw);
    for (int b = 7; b >= 0; b--) {
        fmt_printf(" %u", (unsigned)((sw >> b) & 1u));
    }
    fmt_printf(")\n  Buttons         : 0x%02X  (", (unsigned)btn);
    for (unsigned b = 0; b < 5u; b++) {
        fmt_printf("%c=%u%s", btn_names[b], (unsigned)((btn >> b) & 1u), (b < 4u) ? " " : ")\n");
    }
    fmt_printf("  LEDs            : 0x%02X  (led0 MMCM lock, led1 heartbeat)\n", (unsigned)(leds | ((cs & 1u) ? 1u : 0u)));
    fmt_printf("  PHY pins        : rst_n=%u int_n=%u pme_n=%u mdio=%u rxck=%u rxctl=%u rxd=0x%X\n",
               (unsigned)((phy & NXV_PHY_RST_N) != 0u), (unsigned)((phy & NXV_PHY_INT_N) != 0u),
               (unsigned)((phy & NXV_PHY_PME_N) != 0u), (unsigned)((phy & NXV_PHY_MDIO_IN) != 0u),
               (unsigned)((phy & NXV_PHY_RXCK) != 0u), (unsigned)((phy & NXV_PHY_RXCTL) != 0u),
               (unsigned)((phy & NXV_PHY_RXD_MASK) >> NXV_PHY_RXD_SHIFT));
    return 0;
}

/**
 * @brief SHOW INTERFACES: MAC core status and the eth0 configuration.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_interfaces(const MenuCommandContext *ctx)
{
    (void)ctx;
    (void)cli_core_check(&g_core_mac);
    fmt_printf("eth0 configuration: speed %s%s, autoneg %s, %s\n",
               (g_cfg.speed_mbps == CLI_SPEED_AUTO) ? "auto" : "",
               (g_cfg.speed_mbps == 10u) ? "10" : (g_cfg.speed_mbps == 100u) ? "100" :
               (g_cfg.speed_mbps == 1000u) ? "1000" : "",
               g_cfg.autoneg ? "on" : "off", g_cfg.shutdown ? "shutdown" : "no shutdown");
    return 0;
}

