/**
 * @brief Parse and check a word-aligned address argument.
 * @param s    Address text.
 * @param addr Parsed address.
 * @return 0 on success, -1 (message printed) on a bad or unaligned address.
 */
static int cli_parse_addr(const char *s, uint32_t *addr)
{
    if (cli_parse_u32(s, addr) != 0) {
        return cli_bad_value("address", s);
    }
    if ((*addr & 3u) != 0u) {
        fmt_printf("%% Address 0x%08X is not word aligned\n", (unsigned)*addr);
        return -1;
    }
    return 0;
}

/**
 * @brief DEBUG READ [ADDR]: raw 32-bit read.
 * @param ctx argv[0] = address.
 * @return 0, or -1 for a bad address.
 */
int cli_debug_read(const MenuCommandContext *ctx)
{
    uint32_t addr;
    if (cli_parse_addr(ctx->argv[0], &addr) != 0) {
        return -1;
    }
    fmt_printf("0x%08X = 0x%08X\n", (unsigned)addr, (unsigned)board_debug_read32((uintptr_t)addr));
    return 0;
}

/**
 * @brief DEBUG WRITE [ADDR] [VALUE]: raw 32-bit write, then read back.
 * @param ctx argv[0] = address, argv[1] = value.
 * @return 0, or -1 for a bad address or value.
 */
int cli_debug_write(const MenuCommandContext *ctx)
{
    uint32_t addr;
    uint32_t value;
    if (cli_parse_addr(ctx->argv[0], &addr) != 0) {
        return -1;
    }
    if (cli_parse_u32(ctx->argv[1], &value) != 0) {
        return cli_bad_value("value", ctx->argv[1]);
    }
    board_debug_write32((uintptr_t)addr, value);
    fmt_printf("0x%08X <- 0x%08X (reads back 0x%08X)\n", (unsigned)addr, (unsigned)value,
               (unsigned)board_debug_read32((uintptr_t)addr));
    return 0;
}

/**
 * @brief Common part of LED [N] ON / OFF.
 * @param s  LED index text.
 * @param on 1 on, 0 off.
 * @return 0, or -1 for an index outside 2..7.
 */
static int cli_led(const char *s, int on)
{
    uint32_t n;
    if (cli_parse_u32(s, &n) != 0 || n > CLI_LED_LAST) {
        return cli_bad_value("LED index (2..7)", s);
    }
    if (n < CLI_LED_FIRST_USER) {
        fmt_printf("%% LED %u is not firmware-owned (led0 MMCM lock, led1 heartbeat); use 2..7\n", (unsigned)n);
        return -1;
    }
    plat_led_set((unsigned)n, on);
    fmt_printf("LED %u %s\n", (unsigned)n, on ? "on" : "off");
    return 0;
}

/**
 * @brief LED [N] ON.
 * @param ctx argv[0] = LED index.
 * @return See cli_led.
 */
int cli_led_on(const MenuCommandContext *ctx)
{
    return cli_led(ctx->argv[0], 1);
}

/**
 * @brief LED [N] OFF.
 * @param ctx argv[0] = LED index.
 * @return See cli_led.
 */
int cli_led_off(const MenuCommandContext *ctx)
{
    return cli_led(ctx->argv[0], 0);
}

/**
 * @brief RELOAD: soft restart of the firmware.
 * @param ctx Unused.
 * @return 0 (on the target plat_reload does not return).
 */
int cli_reload(const MenuCommandContext *ctx)
{
    (void)ctx;
    fmt_printf("Reloading...\n");
    plat_reload();
    return 0;
}

